class Solution {
    public long maximumImportance(int n,int[][] roads){
        long[] degree=new long[n];
        for(int[] road:roads){
            degree[road[0]]++;
            degree[road[1]]++;
        }
        Arrays.sort(degree);
        long answer=0;
        for(int i=0;i<n;i++)answer+=degree[i]*(i+1);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumImportance(n:Int,roads:Array<IntArray>):Long{
        val degree=LongArray(n);
        for(road in roads){
            degree[road[0]]++;
            degree[road[1]]++
        };
        degree.sort();
        return degree.indices.sumOf{
            degree[it]*(it+1)
        }
    }
}

